components.calculateValue:
try {
  var ctx = data.lastTripContext ? JSON.parse(data.lastTripContext) : null;
  var months = {
    '1': 'يناير',
    '2': 'فبراير',
    '3': 'مارس',
    '4': 'أبريل',
    '5': 'مايو',
    '6': 'يونيو',
    '7': 'يوليو',
    '8': 'أغسطس',
    '9': 'سبتمبر',
    '10': 'أكتوبر',
    '11': 'نوفمبر',
    '12': 'ديسمبر'
  };
  value = ctx && ctx.hasPreviousTrip && ctx.month ? (months[String(ctx.month.id)] || '') : '';
} catch (e) {
  value = '';
}

try {
  var ctx = data.lastTripContext ? JSON.parse(data.lastTripContext) : null;
  value = ctx && ctx.hasPreviousTrip && ctx.year ? String(ctx.year.id) : '';
} catch (e) {
  value = '';
}
